#include "evo.h"

#include <stddef.h>

/* Generated by tools/build_evo.py. Generation 5 methods only. */
#include "evo.inc"

uint16_t species_prevo(unsigned species)
{
    if (species >= 650)
        return 0;
    return evo_prevo[species];
}

int species_evo_count(unsigned species)
{
    if (species >= 650)
        return 0;
    return evo_count[species];
}

uint16_t species_evo_into(unsigned species, int index)
{
    if (species >= 650 || index < 0 || index >= evo_count[species])
        return 0;
    return evo_into[evo_start[species] + index];
}

const char *species_evo_how(unsigned species, int index)
{
    if (species >= 650 || index < 0 || index >= evo_count[species])
        return "";
    return evo_phrases[evo_phrase[evo_start[species] + index]];
}

const char *species_evo_how_gen(unsigned species, int index, int generation)
{
    const char *how = species_evo_how(species, index);
    unsigned into;

    if (!how[0] || generation > 4)
        return how;
    into = species_evo_into(species, index);
    /* Generations 3 and 4 level Feebas up once its Beauty is high.
       Generation 5 trades it while it holds a Prism Scale. */
    if (species == 349 && into == 350)
        return "High Beauty";
    return how;
}

static int walk_family(unsigned species, int indent, const char *method,
                       EvoMember *out, int n, int cap)
{
    int kids;
    int i;

    if (species < 1 || species > 649 || n >= cap)
        return n;
    out[n].species = (uint16_t)species;
    out[n].indent = (uint8_t)indent;
    out[n].method = method;
    n++;
    kids = evo_count[species];
    for (i = 0; i < kids; i++) {
        int edge = evo_start[species] + i;
        n = walk_family(evo_into[edge], indent + 2, evo_phrases[evo_phrase[edge]], out, n, cap);
    }
    return n;
}

int species_family(unsigned species, EvoMember *out, int cap)
{
    unsigned root;
    int guard = 0;

    if (!out || cap < 1 || species < 1 || species > 649)
        return 0;
    root = species;
    while (evo_prevo[root] && guard++ < 8)
        root = evo_prevo[root];
    return walk_family(root, 0, NULL, out, 0, cap);
}
